using System;
using System.Net;
using System.Net.Http.Headers;
using System.Text;
using System.Threading;

class HttpServer
{
    static void Main(string[] args)
    {
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/");
        listener.Start();

        Console.WriteLine("Server started. Press any key to stop.");

        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            if (request.Url.AbsolutePath == "/hello")
            {
                string responseText = "<html><body>Hello from C#!</body></html>";
                context.Response.ContentLength64 = responseText.Length;
                context.Response.OutputStream.Write(Encoding.ASCII.GetBytes(responseText), 0, responseText.Length);
            }
            else
            {
                context.Response.StatusCode = 404;
            }

            context.Response.Close();
        }
    }
}
```
