// Функция для вычисления интеграла методом прямоугольников
double integrateRectangle(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double result = 0;
    for (int i = 0; i < n; i++) {
        result += f(a + i * h);
    }
    return result * h;
}

// Функция для вычисления интеграла методом трапеций
double integrateTrapzezium(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double result = 0.5 * (f(a) + f(b));
    for (int i = 1; i < n; i++) {
        result += f(a + i * h);
    }
    return result * h;
}

// Функция для вычисления интеграла методом Симпсона
double integrateSimpson(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double result = f(a) + f(b);
    for (int i = 1; i < n; i++) {
        result += 2 * f(a + i * h);
    }
    return result * h / 3;
}

// Функция-обработчик для каждого потока
void threadProc(int id, double (*f)(double), double a, double b, int n, int method, std::mutex& outputMutex) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dis(0.1, 0.5);

    double result = 0;
    for (int i = 0; i < 1000000; i++) { // небольшое количество итераций для имитации вычислений
        // добавим случайную задержку для имитации параллельных вычислений
        std::this_thread::sleep_for(std::chrono::microseconds((int)(dis(gen) * 1000000)));
        switch (method) {
        case 0:
            result = integrateRectangle(f, a, b, n);
            break;
        case 1:
            result = integrateTrapzezium(f, a, b, n);
            break;
        case 2:
            result = integrateSimpson(f, a, b, n);
            break;
        }
    }

    // синхронизируем вывод результата
    outputMutex.lock();
    std::cout << "Thread " << id << ": Result = " << result << std::endl;
    outputMutex.unlock();
}

int main() {
    // создаем мьютекс для синхронизации вывода
    HANDLE outputMutexHandle = CreateMutex(NULL, FALSE, NULL);
    std::mutex outputMutex(outputMutexHandle);

    // функция для вычисления интеграла
    double (*f)(double) = [](double x) { return x * x; };

    // параметры для вычислений
    double a = 0, b = 1;
    int n = 100; // количество шагов для.getMethodов жестких света
    int method = 2; // метод Симпсона

    // создаем n потоков
    HANDLE threads[4];
    for (int i = 0; i < 4; i++) {
        threads[i] = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)&threadProc, (LPVOID)&f, 0, NULL);
    }

    // ожидаем завершения вычислений всеми потоками
    for (int i = 0; i < 4; i++) {
        WaitForSingleObject(threads[i], INFINITE);
    }

    // закрываем потоки
    for (int i = 0; i < 4; i++) {
        CloseHandle(threads[i]);
    }

    return 0;
}
