```javascript
// SessionManager.js
import React, { Component } from 'react';
import { Link } from '@material-ui/core';
import cookies from 'js-cookie';
import { GoogleOAuth } from 'react-google-oauth';

class SessionManager extends Component {
  constructor(props) {
    super(props);
    this.state = {
      isLoggedIn: false,
      token: null,
    };
  }

  handleGoogleAuth = (googleUser) => {
    const token = googleUser.getAuthResponse().id_token;
    cookies.set('token', token, { expires: 365 });
    this.setState({ isLoggedIn: true, token });
  };

  handleGoogleAuthFailure = (error) => {
    console.error(error);
  };

  handleLogout = () => {
    cookies.remove('token');
    this.setState({ isLoggedIn: false, token: null });
  };

  render() {
    const { isLoggedIn, token } = this.state;
    return (
      <div>
        {isLoggedIn ? (
          <div>
            <h3>Welcome, {token}!</h3>
            <Link
              component={Link}
              to="#"
              onClick={this.handleLogout}
              color="secondary"
            >
              Logout
            </Link>
          </div>
        ) : (
          <GoogleOAuth
            clientId="YOUR_CLIENT_ID"
            scope="profile email"
            onSuccess={this.handleGoogleAuth}
            onFailure={this.handleGoogleAuthFailure}
          >
            Login with Google
          </GoogleOAuth>
        )}
      </div>
    );
  }
}

export default SessionManager;
```

